import{_ as t,o,c as i,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse(`{"title":"Video Sources · Beginner's Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/video-sources.md","filePath":"en/features/video-sources.md","lastUpdated":1788515531000}`),n={name:"en/features/video-sources.md"};function a(s,e,l,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="video-sources-·-beginner-s-guide" tabindex="-1">Video Sources · Beginner&#39;s Guide <a class="header-anchor" href="#video-sources-·-beginner-s-guide" aria-label="Permalink to &quot;Video Sources · Beginner&#39;s Guide&quot;">​</a></h1><blockquote><p>From Bilibili series to your own NAS, this article covers all ZViewer video sources.</p></blockquote><hr><h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p>ZViewer supports <strong>9 video sources</strong>, covering online video platforms, direct links, self-hosted storage, and third-party anime sources. In the room&#39;s <strong>&quot;Add Video&quot;</strong> panel, you can switch between video sources at any time based on your needs.</p><table tabindex="0"><thead><tr><th>Source</th><th>Use Case</th><th>Additional Configuration Required</th></tr></thead><tbody><tr><td><strong>Bilibili</strong></td><td>Parse Bilibili video links / BV IDs, supports premium member quality</td><td>Optional (bind account for premium quality)</td></tr><tr><td><strong>MP4 Direct Link</strong></td><td>Play any publicly accessible MP4 video URL directly</td><td>None</td></tr><tr><td><strong>WebDAV</strong></td><td>Mount self-hosted NAS, Synology, NextCloud, and other WebDAV services</td><td>Requires mount point configuration in profile</td></tr><tr><td><strong>FTP</strong></td><td>Mount FTP file server</td><td>Requires mount point configuration in profile</td></tr><tr><td><strong>OpenList</strong></td><td>Mount OpenList directory listing service</td><td>Requires mount point configuration in profile</td></tr><tr><td><strong>Emby</strong></td><td>Mount Emby media server, browse media libraries to select videos</td><td>Requires mount point configuration in profile</td></tr><tr><td><strong>Jellyfin</strong></td><td>Mount Jellyfin media server, browse media libraries to select videos</td><td>Requires mount point configuration in profile</td></tr><tr><td><strong>Anime Sources (Beta)</strong></td><td>Kazumi / AniSubs and other third-party anime data sources</td><td>Requires enabling in the admin panel</td></tr><tr><td><strong>Server Files</strong></td><td>Browse video file directories on the server</td><td>Only available to <code>root</code> users; requires root directory configuration</td></tr></tbody></table><blockquote><p>The first five (Bilibili / MP4 Direct Link / Mounts / Emby / Jellyfin) are the most commonly used video sources. It is recommended that beginners master these first.</p></blockquote><hr><h2 id="_2-bilibili" tabindex="-1">2. Bilibili <a class="header-anchor" href="#_2-bilibili" aria-label="Permalink to &quot;2. Bilibili&quot;">​</a></h2><p>Bilibili is the most commonly used video source in ZViewer. You can paste a Bilibili video link or BV ID directly, and it will be parsed for playback.</p><h3 id="_2-1-adding-a-bilibili-video" tabindex="-1">2.1 Adding a Bilibili Video <a class="header-anchor" href="#_2-1-adding-a-bilibili-video" aria-label="Permalink to &quot;2.1 Adding a Bilibili Video&quot;">​</a></h3><ol><li>Enter a room and find the <strong>&quot;Add Video&quot;</strong> panel at the bottom.</li><li>Switch to the <strong>&quot;Bilibili&quot;</strong> tab.</li><li>Paste a Bilibili video link, <strong>BV ID</strong>, or <strong>AV ID</strong>, for example: <ul><li>Full link: <code>https://www.bilibili.com/video/BV1GJ411x7o</code></li><li>BV ID only: <code>BV1GJ411x7o</code></li><li>AV ID only: <code>av123456</code></li></ul></li><li>Click the <strong>&quot;Parse&quot;</strong> button and wait for parsing to complete.</li><li>Once parsed successfully, the video is automatically added to the video list. Click to play.</li></ol><h3 id="_2-2-switching-quality" tabindex="-1">2.2 Switching Quality <a class="header-anchor" href="#_2-2-switching-quality" aria-label="Permalink to &quot;2.2 Switching Quality&quot;">​</a></h3><p>After parsing, the video defaults to the highest available quality. You can click the <strong>&quot;Quality&quot;</strong> button in the player to switch quality.</p><blockquote><p>When not logged into a Bilibili account, the available quality is limited to <strong>Bilibili&#39;s public quality</strong>, typically 1080P and below.</p></blockquote><h3 id="_2-3-binding-a-bilibili-account-for-premium-member-quality" tabindex="-1">2.3 Binding a Bilibili Account (for Premium Member Quality) <a class="header-anchor" href="#_2-3-binding-a-bilibili-account-for-premium-member-quality" aria-label="Permalink to &quot;2.3 Binding a Bilibili Account (for Premium Member Quality)&quot;">​</a></h3><p>If you have a Bilibili premium membership, you can bind your account to unlock <strong>1080P High Bitrate</strong>, <strong>4K</strong>, and other premium-only quality options.</p><p>ZViewer offers two binding methods:</p><p><strong>Method 1: QR Code Login</strong></p><ol><li>On the ZViewer homepage, click the <strong>user menu</strong> (showing your username) in the top-right corner and select <strong>&quot;Profile&quot;</strong>.</li><li>On the profile page, find the <strong>&quot;Bilibili Binding&quot;</strong> section.</li><li>Click <strong>&quot;Bind Bilibili Account&quot;</strong>; a QR code will be displayed on the page.</li><li>Open the Bilibili mobile app, use the scan feature to scan the QR code, and confirm login.</li><li>After successful binding, the profile page will show your Bilibili username and avatar.</li></ol><p><strong>Method 2: Cookie Login</strong></p><ol><li>On the profile page, in the &quot;Bilibili Binding&quot; section, select <strong>Cookie Login</strong>.</li><li>Paste your Bilibili login cookie string.</li><li>Click confirm; the system validates the cookie and completes the binding.</li></ol><blockquote><p>After binding, all subsequently parsed Bilibili videos will attempt to use premium quality. If the premium membership expires, the system automatically falls back to public quality.</p></blockquote><h3 id="_2-4-danmaku-support" tabindex="-1">2.4 Danmaku Support <a class="header-anchor" href="#_2-4-danmaku-support" aria-label="Permalink to &quot;2.4 Danmaku Support&quot;">​</a></h3><p>ZViewer supports loading Bilibili&#39;s official danmaku. When playing a Bilibili video, click the <strong>&quot;Danmaku&quot;</strong> button in the player to load and display danmaku.</p><hr><h2 id="_3-mp4-direct-link" tabindex="-1">3. MP4 Direct Link <a class="header-anchor" href="#_3-mp4-direct-link" aria-label="Permalink to &quot;3. MP4 Direct Link&quot;">​</a></h2><p>If you have a direct HTTP link to a video file (ending with <code>.mp4</code> or another playable format), you can add it directly to the room for playback.</p><h3 id="adding-steps" tabindex="-1">Adding Steps <a class="header-anchor" href="#adding-steps" aria-label="Permalink to &quot;Adding Steps&quot;">​</a></h3><ol><li>In the <strong>&quot;Add Video&quot;</strong> panel, switch to the <strong>&quot;Direct Link&quot;</strong> tab.</li><li>Paste the direct URL of the video file in the input box, for example: <ul><li><code>https://example.com/videos/my-movie.mp4</code></li><li><code>https://cdn.example.com/stream/abc123.mp4</code></li></ul></li><li>Click the <strong>&quot;Add&quot;</strong> button.</li><li>The video is immediately added to the video list. Click to play.</li></ol><blockquote><p>Make sure the link is publicly accessible and the server has no hotlink protection (Referer restrictions). If playback fails, try pasting the link into your browser&#39;s address bar to test if it is accessible.</p></blockquote><h3 id="subtitle-support" tabindex="-1">Subtitle Support <a class="header-anchor" href="#subtitle-support" aria-label="Permalink to &quot;Subtitle Support&quot;">​</a></h3><p>ZViewer provides a native subtitle system that <strong>no longer converts to WebVTT</strong>. Instead, it directly parses each subtitle format and renders them using HTML/CSS:</p><ul><li>Supports common subtitle formats (SRT, ASS, etc.), with native parsing for better style fidelity.</li><li>Supports three subtitle loading methods: <strong>auto-detect</strong>, <strong>auto-add</strong>, and <strong>manual add</strong>.</li><li>Built-in browser-side playback engine <strong>playsvideo</strong>: containers the browser cannot play directly — <strong>MKV / AVI / TS / WMV</strong> — are automatically remuxed to fMP4 in the browser, and <strong>browser-incompatible audio tracks such as DTS / AC3 / EAC3</strong> are transcoded to AAC in real time in the browser. Everything works automatically with <strong>no admin-panel toggles</strong> and no manual engine selection when adding a movie; the transcode core ships with the frontend assets and no server-side FFmpeg is required.</li></ul><hr><h2 id="_4-webdav-ftp-openlist" tabindex="-1">4. WebDAV / FTP / OpenList <a class="header-anchor" href="#_4-webdav-ftp-openlist" aria-label="Permalink to &quot;4. WebDAV / FTP / OpenList&quot;">​</a></h2><p>These three video sources require you to first configure a <strong>mount point</strong> in your profile, after which you can browse the mounted directory from within a room to select videos.</p><h3 id="_4-1-configuring-a-mount-point" tabindex="-1">4.1 Configuring a Mount Point <a class="header-anchor" href="#_4-1-configuring-a-mount-point" aria-label="Permalink to &quot;4.1 Configuring a Mount Point&quot;">​</a></h3><ol><li>Click the <strong>user menu</strong> in the top-right corner → <strong>&quot;Profile&quot;</strong>.</li><li>On the profile page, find the <strong>&quot;Mount Point Management&quot;</strong> section.</li><li>Depending on your server type, click the corresponding <strong>&quot;Add&quot;</strong> button (WebDAV / FTP / OpenList).</li><li>Fill in the connection information in the form that appears:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Give this mount point a name for easy identification</td><td><code>My NAS</code> / <code>Office FTP</code></td></tr><tr><td><strong>Server Address</strong></td><td>Server IP or domain name</td><td><code>192.168.1.100</code> or <code>nas.example.com</code></td></tr><tr><td><strong>Port</strong></td><td>Service port number</td><td>WebDAV defaults to <code>443</code> (HTTPS) or <code>80</code> (HTTP), FTP defaults to <code>21</code></td></tr><tr><td><strong>Username</strong></td><td>Login username</td><td><code>admin</code></td></tr><tr><td><strong>Password</strong></td><td>Login password</td><td><code>********</code></td></tr><tr><td><strong>Path</strong></td><td>Optional, specifies the starting directory</td><td><code>/video</code> (leave empty to start from root)</td></tr></tbody></table><ol start="5"><li>After filling in, click the <strong>&quot;Test Connection&quot;</strong> button to confirm the connection is successful.</li><li>Once the test passes, click <strong>&quot;Save&quot;</strong>.</li></ol><blockquote><p>If the connection test fails, check whether the server address, port, username, and password are correct, and whether the server allows external access.</p><p><strong>OpenList Notice</strong>: Make sure your OpenList site and account have been granted <strong>offline download permission</strong> (supports direct link playback) and <strong>WebDAV permission</strong>; otherwise, mounting will not work.</p></blockquote><h3 id="_4-2-using-a-mount-point-in-a-room" tabindex="-1">4.2 Using a Mount Point in a Room <a class="header-anchor" href="#_4-2-using-a-mount-point-in-a-room" aria-label="Permalink to &quot;4.2 Using a Mount Point in a Room&quot;">​</a></h3><ol><li>Return to the room. In the <strong>&quot;Add Video&quot;</strong> panel, switch to the corresponding mount tab (<strong>&quot;WebDAV&quot;</strong> / <strong>&quot;FTP&quot;</strong> / <strong>&quot;OpenList&quot;</strong>).</li><li>The panel lists all mount points configured in your profile.</li><li>Click a mount point to enter directory browsing mode.</li><li>Browse folders to find video files (supports <code>.mp4</code>, <code>.mkv</code>, <code>.webm</code>, and other formats).</li><li>Click a video file to add it to the video list and play it.</li></ol><h3 id="_4-3-managing-mount-points" tabindex="-1">4.3 Managing Mount Points <a class="header-anchor" href="#_4-3-managing-mount-points" aria-label="Permalink to &quot;4.3 Managing Mount Points&quot;">​</a></h3><p>In the <strong>&quot;Mount Point Management&quot;</strong> section of your profile, you can:</p><ul><li><strong>Edit</strong>: Click the <strong>&quot;Edit&quot;</strong> icon next to a mount point to modify connection information.</li><li><strong>Delete</strong>: Click the <strong>&quot;Delete&quot;</strong> icon to remove an unused mount point.</li><li><strong>Test</strong>: Click <strong>&quot;Test Connection&quot;</strong> at any time to check if a mount point is available.</li></ul><hr><h2 id="_5-emby-jellyfin" tabindex="-1">5. Emby / Jellyfin <a class="header-anchor" href="#_5-emby-jellyfin" aria-label="Permalink to &quot;5. Emby / Jellyfin&quot;">​</a></h2><p>Emby and Jellyfin are popular home media servers. ZViewer supports mounting both as video sources, allowing you to browse media libraries (movies, series, seasons, episodes) and select videos to add to the room for playback.</p><h3 id="_5-1-configuring-a-mount-point" tabindex="-1">5.1 Configuring a Mount Point <a class="header-anchor" href="#_5-1-configuring-a-mount-point" aria-label="Permalink to &quot;5.1 Configuring a Mount Point&quot;">​</a></h3><ol><li>Click the <strong>user menu</strong> in the top-right corner → <strong>&quot;Profile&quot;</strong>.</li><li>On the profile page, find the <strong>&quot;Mount Point Management&quot;</strong> section.</li><li>Click the <strong>&quot;Add&quot;</strong> button and select <strong>Emby</strong> or <strong>Jellyfin</strong>.</li><li>Fill in the connection information in the form that appears:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Give this mount point a name</td><td><code>My Emby</code> / <code>Home Jellyfin</code></td></tr><tr><td><strong>Server Address</strong></td><td>Emby/Jellyfin server address (include protocol)</td><td><code>http://192.168.1.100:8096</code></td></tr><tr><td><strong>API Key</strong></td><td>Emby/Jellyfin API key (recommended)</td><td><code>xxxxxxxxxxxxxxxx</code></td></tr><tr><td><strong>Username / Password</strong></td><td>Account credentials (alternative to API Key)</td><td><code>admin</code> / <code>********</code></td></tr></tbody></table><blockquote><p><strong>Use either API Key or account credentials.</strong> It is recommended to use an API Key (generated in Emby/Jellyfin admin panel under &quot;Advanced&quot; → &quot;API Keys&quot;), which is more secure and less affected by password policies.</p></blockquote><ol start="5"><li>After filling in, click the <strong>&quot;Test Connection&quot;</strong> button to confirm the connection is successful and the logged-in user is displayed.</li><li>Once the test passes, click <strong>&quot;Save&quot;</strong>.</li></ol><h3 id="_5-2-using-emby-jellyfin-in-a-room" tabindex="-1">5.2 Using Emby / Jellyfin in a Room <a class="header-anchor" href="#_5-2-using-emby-jellyfin-in-a-room" aria-label="Permalink to &quot;5.2 Using Emby / Jellyfin in a Room&quot;">​</a></h3><ol><li>Return to the room. In the <strong>&quot;Add Video&quot;</strong> panel, switch to the <strong>&quot;Emby&quot;</strong> or <strong>&quot;Jellyfin&quot;</strong> tab.</li><li>The panel lists the Emby/Jellyfin mount points you have configured.</li><li>Click a mount point to enter media library browsing mode (two-column layout, same as WebDAV/OpenList).</li><li>Browse hierarchically: <strong>Media Library</strong> → <strong>Movies / Series</strong> → <strong>Season</strong> → <strong>Episode</strong>.</li><li>Click a video (or select multiple) to batch add them to the video list and play.</li></ol><h3 id="_5-3-playback-mode" tabindex="-1">5.3 Playback Mode <a class="header-anchor" href="#_5-3-playback-mode" aria-label="Permalink to &quot;5.3 Playback Mode&quot;">​</a></h3><p>When adding a video, you can choose a playback mode via the <strong>&quot;Playback Mode&quot;</strong> dropdown:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>Server Relay</strong></td><td>The addresses in the playlist point to ZViewer backend relay endpoints, which carry Emby/Jellyfin credentials to request media streams</td><td>Default mode, for scenarios where the browser cannot set Referer/Authorization headers</td></tr><tr><td><strong>Direct Link</strong></td><td>The player directly accesses the media stream URL issued by the Emby/Jellyfin server</td><td>Suitable when the media server and viewers are on the same network with no cross-origin restrictions, reducing server relay traffic</td></tr></tbody></table><blockquote><p><strong>Tip</strong>: Emby and Jellyfin have highly compatible APIs. ZViewer uses the same client implementation, so their functionality is identical.</p></blockquote><h3 id="_5-4-managing-mount-points" tabindex="-1">5.4 Managing Mount Points <a class="header-anchor" href="#_5-4-managing-mount-points" aria-label="Permalink to &quot;5.4 Managing Mount Points&quot;">​</a></h3><p>In the <strong>&quot;Mount Point Management&quot;</strong> section of your profile, you can perform <strong>edit</strong>, <strong>delete</strong>, and <strong>test connection</strong> operations on Emby/Jellyfin mount points, the same as for WebDAV/FTP/OpenList.</p><hr><h2 id="_6-anime-sources-kazumi-anisubs-beta" tabindex="-1">6. Anime Sources (Kazumi / AniSubs, Beta) <a class="header-anchor" href="#_6-anime-sources-kazumi-anisubs-beta" aria-label="Permalink to &quot;6. Anime Sources (Kazumi / AniSubs, Beta)&quot;">​</a></h2><p>Anime sources are a Beta feature of ZViewer, supporting search and playback of anime through Kazumi, AniSubs, or other third-party data sources.</p><h3 id="_6-1-enabling-anime-sources" tabindex="-1">6.1 Enabling Anime Sources <a class="header-anchor" href="#_6-1-enabling-anime-sources" aria-label="Permalink to &quot;6.1 Enabling Anime Sources&quot;">​</a></h3><ol><li>Log in to ZViewer with a <code>root</code> account.</li><li>Go to the <strong>Admin Panel</strong> (click the user menu in the top-right corner → <strong>&quot;Admin Panel&quot;</strong>).</li><li>Find <strong>&quot;Basic Settings&quot;</strong> in the left menu.</li><li>Locate the <strong>&quot;Data Source Configuration&quot;</strong> (<code>dataSourceConfig</code>) section.</li><li>Enable the toggle for anime sources (Kazumi / AniSubs).</li><li>Save the settings.</li></ol><blockquote><p>Anime sources are a Beta feature. Search results may be incomplete. It is recommended to use them alongside Bilibili anime.</p></blockquote><h3 id="_6-2-searching-and-playing-anime" tabindex="-1">6.2 Searching and Playing Anime <a class="header-anchor" href="#_6-2-searching-and-playing-anime" aria-label="Permalink to &quot;6.2 Searching and Playing Anime&quot;">​</a></h3><ol><li>After enabling anime sources, return to the room&#39;s <strong>&quot;Add Video&quot;</strong> panel.</li><li>Switch to the <strong>&quot;Anime&quot;</strong> tab.</li><li>Enter an anime name in the search box (e.g., <code>Spy x Family</code>, <code>Frieren: Beyond Journey&#39;s End</code>).</li><li>Click the <strong>&quot;Search&quot;</strong> button.</li><li>The search results list matching anime. Click the one you want.</li><li>The system loads the episode list for that anime. Select an episode to play.</li></ol><blockquote><p>Loading the anime list for the first time may take a few seconds. Please be patient.</p></blockquote><hr><h2 id="_7-server-files-root-only" tabindex="-1">7. Server Files (root only) <a class="header-anchor" href="#_7-server-files-root-only" aria-label="Permalink to &quot;7. Server Files (root only)&quot;">​</a></h2><p>The <strong>Server Files</strong> feature allows <code>root</code> users to directly access local video directories on the server without setting up additional file services.</p><h3 id="_7-1-configuring-the-root-directory" tabindex="-1">7.1 Configuring the Root Directory <a class="header-anchor" href="#_7-1-configuring-the-root-directory" aria-label="Permalink to &quot;7.1 Configuring the Root Directory&quot;">​</a></h3><ol><li>Log in with a <code>root</code> account.</li><li>Go to <strong>Admin Panel</strong> → <strong>&quot;Basic Settings&quot;</strong>.</li><li>Find the <strong>&quot;Server File Root Directory&quot;</strong> configuration item.</li><li>Enter one or more directory paths on the server (comma-separated), for example: <ul><li><code>/mnt/videos</code></li><li><code>/data/media</code></li></ul></li><li>Save the settings.</li></ol><blockquote><p>Ensure that the ZViewer backend process has <strong>read permission</strong> for these directories. The directory paths are absolute paths on the server, not paths on the browser machine.</p></blockquote><h3 id="_7-2-browsing-and-managing-files" tabindex="-1">7.2 Browsing and Managing Files <a class="header-anchor" href="#_7-2-browsing-and-managing-files" aria-label="Permalink to &quot;7.2 Browsing and Managing Files&quot;">​</a></h3><ol><li>In the room&#39;s <strong>&quot;Add Video&quot;</strong> panel, switch to the <strong>&quot;Server Files&quot;</strong> tab.</li><li>You will see the list of configured root directories.</li><li>Click a directory to enter browsing mode, where you can: <ul><li><strong>Browse folders</strong>: Navigate through directories to find video files.</li><li><strong>Upload files</strong>: Click the <strong>&quot;Upload&quot;</strong> button to select local files and upload them to the current directory (supports batch upload, up to 50 files).</li><li><strong>Create folder</strong>: Click <strong>&quot;New Folder&quot;</strong> to create a subdirectory.</li><li><strong>Rename/Delete</strong>: Rename or delete files or folders.</li></ul></li><li>Click a video file to add it to the video list for playback.</li></ol><blockquote><p>Server file playback is proxied through the ZViewer backend, supporting Range request resume, making seeking very smooth.</p></blockquote><hr><h2 id="_8-zviewercli-local-proxy" tabindex="-1">8. ZViewerCLI Local Proxy <a class="header-anchor" href="#_8-zviewercli-local-proxy" aria-label="Permalink to &quot;8. ZViewerCLI Local Proxy&quot;">​</a></h2><p>ZViewerCLI is an optional but <strong>strongly recommended</strong> local proxy client, primarily addressing two issues:</p><ul><li><strong>Premium Member High Quality</strong>: Uses your local browser&#39;s Bilibili cookies to resolve premium quality video URLs.</li><li><strong>CORS and Hotlink Protection</strong>: Some CDNs restrict cross-origin requests or validate Referer headers. ZViewerCLI proxies and forwards requests locally, automatically injecting the correct headers.</li></ul><h3 id="_8-1-installing-zviewercli" tabindex="-1">8.1 Installing ZViewerCLI <a class="header-anchor" href="#_8-1-installing-zviewercli" aria-label="Permalink to &quot;8.1 Installing ZViewerCLI&quot;">​</a></h3><ol><li>Open the <a href="https://github.com/Zero-wyc/ZViewerCLI/releases" target="_blank" rel="noreferrer">ZViewerCLI Releases page</a>.</li><li>Download the appropriate version for your operating system: <ul><li><strong>Windows</strong>: Download <code>zviewer-cli-windows-x64.zip</code></li><li><strong>Linux</strong>: Download <code>zviewer-cli-linux-x64.tar.gz</code></li></ul></li><li>Extract to any folder.</li></ol><h3 id="_8-2-starting-zviewercli" tabindex="-1">8.2 Starting ZViewerCLI <a class="header-anchor" href="#_8-2-starting-zviewercli" aria-label="Permalink to &quot;8.2 Starting ZViewerCLI&quot;">​</a></h3><p><strong>Windows</strong>: Double-click <code>zviewer-cli.exe</code>, or run it in a terminal:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">zviewer-cli.exe</span></span></code></pre></div><p><strong>Linux</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./zviewer-cli</span></span></code></pre></div><p>Once started, ZViewerCLI automatically registers with the ZViewer server via WebSocket. The frontend <strong>auto-detects</strong> the local proxy and will prioritize using it to resolve video streams.</p><h3 id="_8-3-verification" tabindex="-1">8.3 Verification <a class="header-anchor" href="#_8-3-verification" aria-label="Permalink to &quot;8.3 Verification&quot;">​</a></h3><p>After ZViewerCLI starts, when playing a Bilibili video in ZViewer, if you see previously unavailable high-quality options (such as <strong>1080P High Bitrate</strong>, <strong>4K</strong>) in the quality menu, the proxy is active.</p><blockquote><p>ZViewerCLI only needs to run on the <strong>viewer&#39;s</strong> local machine, not on the server. If multiple people are watching, each person can run ZViewerCLI on their own machine for the best quality.</p></blockquote><hr><h2 id="_9-frequently-asked-questions" tabindex="-1">9. Frequently Asked Questions <a class="header-anchor" href="#_9-frequently-asked-questions" aria-label="Permalink to &quot;9. Frequently Asked Questions&quot;">​</a></h2><h3 id="q-why-does-my-bilibili-video-fail-to-parse" tabindex="-1">Q: Why does my Bilibili video fail to parse? <a class="header-anchor" href="#q-why-does-my-bilibili-video-fail-to-parse" aria-label="Permalink to &quot;Q: Why does my Bilibili video fail to parse?&quot;">​</a></h3><p>A: Possible reasons:</p><ul><li>The BV ID or link format is incorrect. Check that it was copied completely.</li><li>The video is not publicly accessible on Bilibili (e.g., a private upload).</li><li>The server cannot reach the Bilibili API.</li><li>If ZViewerCLI is enabled, verify that it is running.</li></ul><h3 id="q-an-mp4-direct-link-was-added-but-won-t-play" tabindex="-1">Q: An MP4 direct link was added but won&#39;t play? <a class="header-anchor" href="#q-an-mp4-direct-link-was-added-but-won-t-play" aria-label="Permalink to &quot;Q: An MP4 direct link was added but won&#39;t play?&quot;">​</a></h3><p>A: Check the following:</p><ul><li>Does the link start with <code>https://</code> or <code>http://</code>?</li><li>Can the link be opened directly in a browser?</li><li>Does the target server have hotlink protection (Referer restrictions)?</li><li>Is the video format supported (<code>.mp4</code> / <code>.mkv</code> / <code>.avi</code> / <code>.ts</code> / <code>.wmv</code> all work — containers the browser cannot play directly are automatically remuxed by the playsvideo engine)?</li></ul><h3 id="q-webdav-ftp-connection-test-fails" tabindex="-1">Q: WebDAV / FTP connection test fails? <a class="header-anchor" href="#q-webdav-ftp-connection-test-fails" aria-label="Permalink to &quot;Q: WebDAV / FTP connection test fails?&quot;">​</a></h3><p>A: Common causes:</p><ul><li>Incorrect server address or port.</li><li>Incorrect username or password.</li><li>The server firewall is blocking external connections.</li><li>The WebDAV server does not have HTTPS enabled (some browsers restrict HTTPS pages from accessing HTTP resources).</li><li>If using a self-hosted NAS, check that the corresponding service is enabled.</li></ul><h3 id="q-anime-source-search-returns-no-results" tabindex="-1">Q: Anime source search returns no results? <a class="header-anchor" href="#q-anime-source-search-returns-no-results" aria-label="Permalink to &quot;Q: Anime source search returns no results?&quot;">​</a></h3><p>A: Anime sources are a Beta feature. Possible reasons:</p><ul><li>The anime source toggle is not enabled in the admin panel.</li><li>The data source configuration is empty or invalid.</li><li>The anime name is not accurate. Try using the original Japanese name or the Chinese translation.</li><li>The data source server is temporarily unavailable.</li></ul><h3 id="q-emby-jellyfin-connection-test-fails" tabindex="-1">Q: Emby / Jellyfin connection test fails? <a class="header-anchor" href="#q-emby-jellyfin-connection-test-fails" aria-label="Permalink to &quot;Q: Emby / Jellyfin connection test fails?&quot;">​</a></h3><p>A: Common causes:</p><ul><li>Incorrect server address format. The protocol must be included (e.g., <code>http://192.168.1.100:8096</code>).</li><li>Incorrect API Key or username/password.</li><li>The Emby/Jellyfin server does not have external access enabled.</li><li>The server firewall is blocking the connection.</li></ul><h3 id="q-emby-jellyfin-playback-is-choppy-or-shows-a-black-screen" tabindex="-1">Q: Emby / Jellyfin playback is choppy or shows a black screen? <a class="header-anchor" href="#q-emby-jellyfin-playback-is-choppy-or-shows-a-black-screen" aria-label="Permalink to &quot;Q: Emby / Jellyfin playback is choppy or shows a black screen?&quot;">​</a></h3><p>A: Try switching the playback mode:</p><ul><li>If currently on <strong>Direct Link</strong>, switch to <strong>Server Relay</strong> (browser hotlink protection).</li><li>If currently on <strong>Server Relay</strong>, switch to <strong>Direct Link</strong> if network conditions allow, to reduce relay overhead.</li></ul><h3 id="q-zviewercli-has-no-effect-after-starting" tabindex="-1">Q: ZViewerCLI has no effect after starting? <a class="header-anchor" href="#q-zviewercli-has-no-effect-after-starting" aria-label="Permalink to &quot;Q: ZViewerCLI has no effect after starting?&quot;">​</a></h3><p>A: Check the following:</p><ul><li>Did ZViewerCLI start successfully (any error messages in the terminal)?</li><li>Is it running on the <strong>viewer&#39;s</strong> local machine (not on the server)?</li><li>Is the firewall blocking ZViewerCLI&#39;s network connection?</li><li>Try restarting ZViewerCLI and refreshing the ZViewer page.</li></ul><h3 id="q-how-do-i-see-which-video-sources-i-have-bound" tabindex="-1">Q: How do I see which video sources I have bound? <a class="header-anchor" href="#q-how-do-i-see-which-video-sources-i-have-bound" aria-label="Permalink to &quot;Q: How do I see which video sources I have bound?&quot;">​</a></h3><p>A: On the profile page, you can see:</p><ul><li><strong>Bilibili Binding Status</strong>: Shows the bound username.</li><li><strong>Mount Point List</strong>: Shows all configured WebDAV / FTP / OpenList mount points.</li></ul><h3 id="q-why-can-t-i-see-the-server-files-feature" tabindex="-1">Q: Why can&#39;t I see the Server Files feature? <a class="header-anchor" href="#q-why-can-t-i-see-the-server-files-feature" aria-label="Permalink to &quot;Q: Why can&#39;t I see the Server Files feature?&quot;">​</a></h3><p>A: The Server Files feature is only visible to users with the <strong><code>root</code> role</strong>. If you are logged in with a regular user account, this tab will not be displayed. Contact the administrator or log in with a <code>root</code> account.</p><hr><blockquote><p>More questions? See the <a href="/en/guide/faq">FAQ</a> or contact the administrator.</p></blockquote>',126)])])}const p=t(n,[["render",a]]);export{g as __pageData,p as default};
